const execFileAsync = promisify(execFile);

const projectFile = (relativePath) => fileURLToPath(
  new URL(`../${relativePath.replace(/^\.\//, "")}`, import.meta.url)
);

async function listJavaScriptFiles(directory = projectFile("js")) {
  const entries = await readdir(directory, { withFileTypes: true });
  const nested = await Promise.all(entries.map((entry) => {
    const path = `${directory}/${entry.name}`;
    return entry.isDirectory() ? listJavaScriptFiles(
      path
    ) : (entry.isFile() && entry.name.endsWith(".js") ? [path] : []);
  }));
  return nested.flat();
}

let serial = 0;

const instance = (definitionId) => (
  { ...CARD_DEFINITIONS[definitionId], id: `test-card-${definitionId}-${++serial}` }
);

const assertClose = (actual, expected, epsilon = 1e-9) => assert.ok(
  Math.abs(actual - expected) <= epsilon, `expected ${actual} to be within ${epsilon} of ${expected}`
);

function makeUi(response = () => false) {
  return {
    logs: [],
    reveals: [],
    responseRequests: [],
    publicRequests: [],
    hiddenRequests: [],
    thinking: [],
    currentCards: [],
    judgments: [],
    playEndState: null,
    render() { },
    appendLog(entry) { this.logs.push(entry.message); },
    waitForHumanPlayEnd(
      gameId
    ) { return new Promise((resolve) => { this.playEndState = { gameId, resolve }; }); },
    resolveHumanPlayEnd(
      gameId
    ) { if (!this.playEndState || this.playEndState.gameId !== gameId) return; const resolve = this.playEndState.resolve; this.playEndState = null; resolve(true); },
    cancelPendingInteractions() {
      if (
        this.playEndState
      ) { const resolve = this.playEndState.resolve; this.playEndState = null; resolve(false); }
    },
    async requestResponse(request) {
      this.responseRequests.push(request);
      const decision = await response(request);
      if (decision === true) {
        return {
          status:"used",
          selectedIds:request.legalCardIds.slice(0, request.requiredCount)
        };
      }
      return decision === false ? { status:"declined" } : decision;
    },
    async requestDiscard(player, count) { return player.hand.slice(0, count); },
    async requestTarget(players) { return players[0] ?? null; },
    async requestPublicCard(
      _player, cards
    ) { this.publicRequests.push(cards.map((card) => card.id)); return cards[0] ?? null; },
    async requestHiddenCards(
      selection, count, prompt, options = {}
    ) { this.hiddenRequests.push({ selection, count, prompt, options }); return selection.tokens.slice(0, count).map((entry) => entry.token); },
    async showPrivateReveal(title, cards = []) { this.reveals.push({ title, cards: [...cards] }); },
    setCurrentCard(
      cardOrName, source, targetLabel = "", displayTargets = null
    ) { this.currentCards.push({ cardOrName, source, targetLabel, displayTargets }); },
    setPrompt() { },
    setThinking(...args) { this.thinking.push(args); },
    showGameOver() { },
    queueFeedback() { },
    showDying() { },
    hideDying() { },
    showPublicPool() { },
    hidePublicPool() { },
    showJudgment(player, card, context = {}) { this.judgments.push({ player, card, context }); },
    hideJudgment() { },
    showDuel() { },
    hideDuel() { }
  };
}

function makePlayer(id, seatIndex, team, controllerType = "ai", characterIndex = seatIndex % 8) {
  const player = new Player({ id, seatIndex, battleTeam: team, controllerType });
  player.applyCharacter(TEST_VERSION_STATE, CHARACTER_DEFINITIONS[characterIndex]);
  player.resetRoundFlags(TEST_VERSION_STATE);
  return player;
}

function makeGame(players, { random = () => 0.25, response = () => false } = {}) {
  const ui = makeUi(response);
  const game = createGameApplication(ui, random);
  game.aiRandom = {
    next: random,
    snapshot: () => ({ seed: 0, state: 0, algorithm: "lcg", draws: 0 }),
    commit: () => {}
  };
  game.aiController.searchRng = game.aiRandom;
  game.state.players = players;
  game.state.currentPlayerIndex = 0;
  game.state.startingPlayerIndex = 0;
  game.state.phase = "play";
  game.simulationMode = true;
  game.cleanupManager.delay = async () => !game.state.isDisposed;
  for (const player of players) {
    player.maxEnergy = game.teamRules.getMaxEnergy(player);
    player.energy = Math.min(player.energy, player.maxEnergy);
    player.resetTurnFlags(TEST_VERSION_STATE, game.teamRules.getRules(player));
  }
  game.registerGlobalRules();
  return { game, ui };
}

/** 统一按实体引用检查抽牌、手牌、装备、弃牌、结算、判定和公共牌池。 */
function assertCardOnlyIn(game, card, expectedZone) {
  assert.deepEqual(game.getCardZoneOccurrences(card), [expectedZone]);
}

function makeOwnedUi() {
  return {
    game: null,
    renders: [],
    mutations: [],
    logs: [],
    responseState: null,
    targetState: null,
    discardState: null,
    publicState: null,
    attachGame: UIManager.prototype.attachGame,
    isGameAttached: UIManager.prototype.isGameAttached,
    createGameSession: UIManager.prototype.createGameSession,
    render(
      game
    ) { if (!this.isGameAttached(game)) return false; this.renders.push(game.state.gameId); return true; },
    appendLog(entry) { this.logs.push(entry.message); },
    setPrompt(message) { this.mutations.push(["prompt", message]); },
    setThinking(value) { this.mutations.push(["thinking", value]); },
    setCurrentCard(card) { this.mutations.push(["card", card?.id ?? card]); },
    queueFeedback() { },
    setFastMode() { },
    resolveHumanPlayEnd() { },
    requestResponse(
      request
    ) { return new Promise((resolve) => { this.responseState = { request, resolve }; this.onResponse?.(request); }); },
    requestTarget() {
      return new Promise((resolve) => { this.targetState = { resolve }; this.onTarget?.(); });
    },
    requestDiscard() {
      return new Promise((resolve) => { this.discardState = { resolve }; this.onDiscard?.(); });
    },
    requestPublicCard() {
      return new Promise((resolve) => { this.publicState = { resolve }; this.onPublic?.(); });
    },
    waitForHumanPlayEnd() { return Promise.resolve(true); },
    showPrivateReveal() { },
    showPublicPool() { },
    hidePublicPool() { },
    showJudgment() { },
    hideJudgment() { },
    showDying() { },
    hideDying() { },
    showDuel() { },
    hideDuel() { },
    showGameOver() { },
    cancelPendingInteractions() {
      if (
        this.responseState
      ) { const { resolve } = this.responseState; this.responseState = null; resolve({ status: "cancelled" }); } if (this.targetState) { const { resolve } = this.targetState; this.targetState = null; resolve(null); } if (this.discardState) { const { resolve } = this.discardState; this.discardState = null; resolve([]); } if (this.publicState) { const { resolve } = this.publicState; this.publicState = null; resolve(null); }
    }
  };
}

function configureOwnedGame(game, players) {
  game.state.players = players;
  game.state.currentPlayerIndex = 0;
  game.state.startingPlayerIndex = 0;
  game.state.phase = "play";
  game.simulationMode = true;
  game.cleanupManager.delay = async () => !game.state.isDisposed;
  for (const player of players) {
    player.maxEnergy = game.teamRules.getMaxEnergy(player);
    player.resetTurnFlags(TEST_VERSION_STATE, game.teamRules.getRules(player));
  }
  return game;
}

function makeTeamFixture() {
  const small = makePlayer("small", 0, "dawn", "ai", 0),
    large = makePlayer("large", 1, "dusk", "ai", 0);
  const smallAlly = makePlayer("small-ally", 2, "dawn"),
    largeAlly1 = makePlayer("large-ally-1", 3, "dusk"),
    largeAlly2 = makePlayer("large-ally-2", 4, "dusk");
  const fixture = makeGame([small, large, smallAlly, largeAlly1, largeAlly2]);
  return { ...fixture, small, large };
}

function makeInteractiveElement() {
  const listeners = new Map();
  const classes = new Set(["is-hidden"]);
  return {
    innerHTML: "",
    listeners,
    classList: {
      add: (name) => classes.add(name),
      remove: (name) => classes.delete(name),
      contains: (name) => classes.has(name)
    },
    addEventListener: (type, handler) => listeners.set(type, handler),
    removeEventListener: (type, handler) => {
      if (listeners.get(type) === handler) listeners.delete(type);
    },
    click(target) { listeners.get("click")?.({ target }); }
  };
}

function clickTarget(selector, dataset = {}) {
  return { dataset, closest: (query) => query === selector ? { dataset } : null };
}

async function choosePrivateCardThroughInteraction(game, actor, card, target, { handIndexes = [0], equipment = false } = {}) {
  const ui = { async requestTarget(players) { return players[0] ?? null; } };
  const controller = new InteractionController(ui);
  const flowSelection = await controller.requestCardFlow(game, actor, card, [target]);
  const hidden = game.hiddenCardSelection.createHiddenSelection(target);
  if (equipment) {
    return {
      ...flowSelection,
      zone: "equipment",
      equipmentCardId: target.equipment?.id ?? null,
      selectionId: hidden.selectionId
    };
  }
  return {
    ...flowSelection,
    zone: "hand",
    tokens: handIndexes.map((index) => hidden.tokens[index]?.token).filter(Boolean),
    selectionId: hidden.selectionId
  };
}

function assertNoHiddenSelectionLeak(value, hiddenCards) {
  const seen = new Set();
  const visit = (entry) => {
    if (!entry || typeof entry !== "object" || seen.has(entry)) return;
    seen.add(entry);
    for (const hidden of hiddenCards) assert.notEqual(entry, hidden, "公开上下文包含隐藏实体对象");
    for (const nested of Object.values(entry)) visit(nested);
  };
  visit(value);
  const serialized = JSON.stringify(value);
  for (const hidden of hiddenCards) {
    for (const secret of [hidden.id, hidden.definitionId, hidden.name, hidden.description]) {
      if (secret) assert.equal(serialized.includes(secret), false, `公开上下文泄露隐藏字段：${secret}`);
    }
  }
}

function forceAvailableAiCounters(game, capturedContexts = []) {
  game.aiController.responsePolicy.shouldRespond = (_responder, type, context, cards) => {
    capturedContexts.push(context);
    return type === "counter" && cards.length > 0;
  };
}


