test("转移：锁定牌在结算前离开来源时转移失败且没有有效目标、成功日志或协调", async () => {
  const tuner = makePlayer("tuner", 0, "dawn", "ai", 7),
    from = makePlayer("from", 1, "dusk"),
    escaped = makePlayer("escaped", 2, "dusk"),
    ally = makePlayer("ally", 3, "dawn"),
    use = instance("transfer"),
    locked = instance("block");
  tuner.hand.push(use);
  from.hand.push(locked);
  const { game }
    = makeGame([tuner, from, escaped, ally]);
  game.state.deck.cards.push(instance("charge"));
  registerPassiveSkills(game);
  let usedEvent = null;
  game.eventDispatcher.on("beforeCardResolve", "test:remove-locked-transfer-card", () => {
    const index = from.hand.indexOf(locked);
    if (index >= 0) {
      from.hand.splice(index, 1);
      escaped.hand.push(locked);
      from.bumpHandVersion(TEST_VERSION_STATE);
      escaped.bumpHandVersion(TEST_VERSION_STATE);
    }
  });
  game.eventDispatcher.on("cardUsed", "test:failed-transfer", (event) => {
    usedEvent = event;
  });
  assert.equal(
    await game.playCard(tuner, use, [], { sourceId: from.id, receiverId: ally.id, zone: "hand" }), true
  );
  assert.ok(escaped.hand.includes(locked));
  assert.ok(!ally.hand.includes(locked));
  assert.ok(game.state.deck.discardPile.includes(use));
  assert.ok(!game.state.deck.resolvingCards.includes(use));
  assert.equal(tuner.turnFlags.coordinationTriggered, false);
  assert.equal(tuner.hand.length, 0);
  assert.ok(usedEvent);
  assert.equal(usedEvent.cancelled, true);
  assert.equal(usedEvent.resolved, false);
  assert.deepEqual(usedEvent.effectiveTargets, []);
  assert.equal(
    game.state.logs.some(
      (entry) => entry.message.includes(
        `${tuner.name}将${from.name}的`
      ) && entry.message.includes(`转移给了${ally.name}`)
    ),
    false
  );
});

