test("转移：伪造装备区转移不会开启反制窗口或生成公开转移上下文", async () => {
  const actor = makePlayer("actor", 0, "dawn"),
    from = makePlayer("from", 1, "dusk"),
    responder = makePlayer("responder", 2, "dusk"),
    receiver = makePlayer("receiver", 3, "dawn");
  const use = instance("transfer"), radar = instance("defenseDevice"), held = instance("block");
  actor.hand.push(use);
  from.hand.push(held);
  from.equipment = radar;
  responder.hand.push(instance("counter"));
  const { game }
    = makeGame([actor, from, responder, receiver]);
  let publicContext = null;
  game.aiController.responsePolicy.shouldRespond = (_player, _type, context) => {
    publicContext = context.publicTransferContext;
    return false;
  };
  const selection = game.hiddenCardSelection.createHiddenSelection(from);
  assert.equal(
    await game.playCard(
      actor,
      use,
      [],
      {
        sourceId: from.id,
        receiverId: receiver.id,
        zone: "equipment",
        equipmentCardId: radar.id,
        selectionId: selection.selectionId
      }
    ),
    false
  );
  assert.equal(publicContext, null);
  assert.equal(from.equipment, radar);
  assert.ok(actor.hand.includes(use));
  assert.equal(game.state.pendingResponses.length, 0);
});

