test("闪电：判定成功日志复用玩家与卡牌名称格式化机制", async () => {
  const holder = makePlayer("a", 0, "dawn"), enemy = makePlayer("b", 1, "dusk");
  const { game }
    = makeGame([holder, enemy]);
  holder.statuses.lightning = { cardDefinitionId: "lightning", originPlayerId: holder.id };
  const equipment = instance("defenseDevice");
  game.state.deck.cards = [equipment];
  await game.eventDispatcher.emit("beforeStatusResolve", { player: holder, cancelled: false });
  const reveal = game.state.logs.find((entry) => entry.message.includes("判定为"));
  const trigger = game.state.logs.find((entry) => entry.message.includes("判定成功"));
  assert.ok(reveal);
  assert.ok(trigger);
  assert.equal(reveal.message, `${holder.name}的「闪电」判定为「${equipment.name}」，为装备牌。`);
  assert.equal(trigger.message, `${holder.name}的「闪电」判定成功，被「闪电」击中。`);
  assert.equal(game.state.logs.filter((entry) => entry.message.includes("装备牌")).length, 1);
  assert.ok(
    reveal.fragments.some((fragment) => fragment.type === "player" && fragment.playerId === holder.id)
  );
  const rendered = formatLogEntry(reveal);
  assert.match(rendered, /log-player-name/);
  assert.match(rendered, /log-card-name/);
  assert.ok(rendered.includes("「<strong class=\"log-card-name\">闪电</strong>」"));
  assert.ok(rendered.includes(`「<strong class="log-card-name">${equipment.name}</strong>」`));
  for (const entry of game.state.logs) {
    assert.ok(
      !entry.message.includes("【") && !entry.message.includes("】"), `日志不得使用【】：${entry.message}`
    );
    assert.ok(!entry.message.includes("“闪电”"), `日志不得使用弯引号“闪电”：${entry.message}`);
  }
});

test("闪电：基础牌与战术牌判定类别日志正确", async () => {
  const run = (judgmentDefinitionId) => {
    const holder = makePlayer("a", 0, "dawn"), enemy = makePlayer("b", 1, "dusk");
    const { game }
      = makeGame([holder, enemy]);
    holder.statuses.lightning = { cardDefinitionId: "lightning", originPlayerId: holder.id };
    const judgmentCard = instance(judgmentDefinitionId);
    game.state.deck.cards = [judgmentCard];
    return { game, holder, enemy, judgmentCard };
  };
  const basic = run("assault");
  await basic.game.eventDispatcher.emit("beforeStatusResolve", { player: basic.holder, cancelled: false });
  assert.ok(
    basic.game.state.logs.some(
      (entry) => entry.message === `${basic.holder.name}的「闪电」判定为「${basic.judgmentCard.name}」，为基础牌。`
    )
  );
  assert.ok(
    basic.game.state.logs.some(
      (entry) => entry.message === `${basic.holder.name}的「闪电」判定未生效，转移给${basic.enemy.name}。`
    )
  );
  const tactic = run("harvest");
  await tactic.game.eventDispatcher.emit("beforeStatusResolve", { player: tactic.holder, cancelled: false });
  assert.ok(
    tactic.game.state.logs.some(
      (entry) => entry.message === `${tactic.holder.name}的「闪电」判定为「${tactic.judgmentCard.name}」，为战术牌。`
    )
  );
  assert.ok(
    tactic.game.state.logs.some(
      (entry) => entry.message === `${tactic.holder.name}的「闪电」判定未生效，转移给${tactic.enemy.name}。`
    )
  );
  assert.equal(tactic.game.state.logs.filter((entry) => entry.message.includes("战术牌")).length, 1);
});

