test("影客：窃取可把距离2内敌方装备收入手牌且不替换原装备", async () => {
  const shade = makePlayer("shade", 0, "dawn", "ai", 3),
    near = makePlayer("near", 1, "dawn"),
    target = makePlayer("target", 2, "dusk"),
    other = makePlayer("other", 3, "dusk"),
    tail = makePlayer("tail", 4, "dawn"),
    equipment = instance("energyDevice"),
    original = instance("battleDevice");
  const { game }
    = makeGame([shade, near, target, other, tail], { random: () => 0 });
  shade.energy = 2;
  shade.equipment = original;
  target.equipment = equipment;
  assert.ok(ActionLegality.getSkillTargets(game, shade, ACTIVE_SKILLS.stealSkill).includes(target));
  assert.equal(await game.useActiveSkill(shade, "stealSkill", [target]), true);
  assert.equal(target.equipment, null);
  assert.equal(shade.equipment, original);
  assert.ok(shade.hand.includes(equipment));
  assert.ok(!game.state.deck.discardPile.includes(equipment));
  const blockedShade = makePlayer("blocked-shade", 0, "dawn", "ai", 3),
    blockedNear = makePlayer("blocked-near", 1, "dawn"),
    blocked = makePlayer("blocked", 2, "dusk"),
    blockedOther = makePlayer("blocked-other", 3, "dusk"),
    blockedTail = makePlayer("blocked-tail", 4, "dawn");
  blocked.equipment = instance("barrierDevice");
  const { game: blockedGame }
    = makeGame([blockedShade, blockedNear, blocked, blockedOther, blockedTail]);
  assert.equal(ActionLegality.getDistance(blockedGame, blockedShade, blocked), 3);
  assert.ok(
    !ActionLegality.getSkillTargets(blockedGame, blockedShade, ACTIVE_SKILLS.stealSkill).includes(blocked)
  );
});

test("影客：窃取把3张手牌与1张装备组成单一等概率实体集合", async () => {
  const rolls = [0, .26, .51, .76];
  for (const [expectedIndex, roll] of rolls.entries()) {
    const shade = makePlayer(`uniform-shade-${expectedIndex}`, 0, "dawn", "ai", 3),
      target = makePlayer(`uniform-target-${expectedIndex}`, 1, "dusk");
    const cards = [instance("assault"), instance("recover"), instance("charge")],
      equipment = instance("recycleDevice"),
      original = instance("battleDevice");
    target.hand.push(...cards);
    target.equipment = equipment;
    shade.equipment = original;
    shade.energy = 2;
    const { game }
      = makeGame([shade, target], { random: () => roll }),
      candidate = [...cards, equipment][expectedIndex];
    const shadeVersion = shade.handVersion, targetVersion = target.handVersion;
    assert.equal(await game.useActiveSkill(shade, "stealSkill", [target]), true);
    assert.deepEqual(shade.hand, [candidate]);
    assert.equal(shade.equipment, original);
    assert.equal(shade.handVersion, shadeVersion + 1);
    assert.equal(target.hand.includes(candidate), false);
    assert.equal(target.equipment === candidate, false);
    assert.equal(game.state.deck.discardPile.includes(candidate), false);
    assert.equal(game.state.deck.resolvingCards.includes(candidate), false);
    assert.equal(target.handVersion, targetVersion + (expectedIndex < 3 ? 1 : 0));
    const zones = [
      shade.hand.includes(candidate),
      shade.equipment === candidate,
      target.hand.includes(candidate),
      target.equipment === candidate,
      game.state.deck.discardPile.includes(candidate)
    ];
    assert.equal(zones.filter(Boolean).length, 1);
  }
});

test("影客：真人窃取先选择距离2内敌人再只从该目标随机获得资源", async () => {
  const shade = makePlayer("human-steal-shade", 0, "dawn", "human", 3),
    allyA = makePlayer("human-steal-ally-a", 1, "dawn"),
    chosen = makePlayer("human-steal-chosen", 2, "dusk"),
    otherEnemy = makePlayer("human-steal-other", 3, "dusk"),
    allyB = makePlayer("human-steal-ally-b", 4, "dawn"),
    chosenEquipment = instance("energyDevice"),
    untouched = instance("block");
  chosen.equipment = chosenEquipment;
  otherEnemy.hand.push(untouched);
  shade.energy = 2;
  const { game, ui }
    = makeGame([shade, allyA, chosen, otherEnemy, allyB], { random: () => 0 });
  let offered = null, prompt = "";
  ui.requestTarget = async (players, message) => {
    offered = [...players];
    prompt = message;
    return chosen;
  };
  assert.equal(await game.handleHumanSkill(), true);
  assert.ok(offered.includes(chosen));
  assert.ok(offered.includes(otherEnemy));
  assert.ok(
    offered.every(
      (player) => player.battleTeam !== shade.battleTeam && ActionLegality.getDistance(
        game, shade, player
      ) <= 2
    )
  );
  assert.match(prompt, /窃取.*选择目标/);
  assert.equal(chosen.equipment, null);
  assert.ok(shade.hand.includes(chosenEquipment));
  assert.ok(otherEnemy.hand.includes(untouched));
  assert.equal(shade.energy, 0);
});

test("影客：窃取装备先进入手牌且只有之后正常使用才会装备和替换", async () => {
  const shade = makePlayer("equip-to-hand-shade", 0, "dawn", "ai", 3),
    target = makePlayer("equip-to-hand-target", 1, "dusk"),
    stolen = instance("energyDevice"),
    original = instance("battleDevice");
  const { game }
    = makeGame([shade, target], { random: () => 0 });
  shade.energy = 2;
  shade.equipment = original;
  target.equipment = stolen;
  const moves = [];
  game.eventDispatcher.on("afterCardMove", "test:steal-equipment-zone", (event) => {
    if (event.card === stolen) moves.push([event.from, event.to]);
  });
  assert.equal(await game.useActiveSkill(shade, "stealSkill", [target]), true);
  assert.deepEqual(moves, [["equipment", "hand"]]);
  assert.equal(shade.equipment, original);
  assert.ok(shade.hand.includes(stolen));
  assert.equal(shade.turnFlags.recycleDeviceUses, 0);
  assert.equal(await game.playCard(shade, stolen, []), true);
  assert.equal(shade.equipment, stolen);
  assert.ok(game.state.deck.discardPile.includes(original));
});

