test("调律师：被下一层反制取消的反制不产生有效结算且不触发协调", async () => {
  const enemy = makePlayer("counter-chain-source", 0, "dusk", "human"),
    tuner = makePlayer("counter-chain-tuner", 1, "dawn", "human", 7),
    counterer = makePlayer("counter-chain-counterer", 2, "dusk", "human"),
    ally = makePlayer("counter-chain-ally", 3, "dawn"),
    use = instance("scout"),
    tunerCounter = instance("counter"),
    nextCounter = instance("counter"),
    secret = instance("block"),
    { game } = makeGame([enemy, tuner, counterer, ally], {
      response: (request) => (
        request.type === "counter"
        && ((request.cardId === use.id && request.targetPlayerId === tuner.id)
          || (request.cardId === tunerCounter.id && request.targetPlayerId === counterer.id))
      )
    });
  enemy.hand.push(use);
  tuner.hand.push(tunerCounter);
  counterer.hand.push(nextCounter);
  ally.hand.push(secret);
  ally.bumpHandVersion(TEST_VERSION_STATE);
  game.state.deck.cards.push(instance("charge"));
  registerPassiveSkills(game);
  const resolvedCounterIds = [];
  game.eventDispatcher.on("cardUsed", "test:counter-chain-effective-use", (event) => {
    if (event.card.definitionId === "counter") resolvedCounterIds.push(event.card.id);
  });
  const hidden = game.hiddenCardSelection.createHiddenSelection(ally);
  assert.equal(await game.playCard(enemy, use, [ally], {
    tokens: [hidden.tokens[0].token], selectionId: hidden.selectionId
  }), true);
  assert.equal(tuner.turnFlags.coordinationTriggered, false);
  assert.ok(!resolvedCounterIds.includes(tunerCounter.id));
  assert.deepEqual(resolvedCounterIds, [nextCounter.id]);
});

test("调律师：beforeCardUse 与 beforeCardResolve 取消的牌都不触发协调", async () => {
  for (const hook of ["beforeCardUse", "beforeCardResolve"]) {
    const tuner = makePlayer(`tuner-${hook}`, 0, "dawn", "ai", 7),
      ally = makePlayer(`ally-${hook}`, 1, "dawn"),
      enemy = makePlayer(`enemy-${hook}`, 2, "dusk"),
      use = instance("mutualBenefit");
    tuner.hand.push(use);
    const { game }
      = makeGame([tuner, ally, enemy]);
    registerPassiveSkills(game);
    game.eventDispatcher.on(hook, `test-cancel-${hook}`, (event) => {
      event.cancelled = true;
    });
    await game.playCard(tuner, use, []);
    assert.equal(tuner.turnFlags.coordinationTriggered, false);
    assert.equal(game.state.publicCardPool.length, 0);
  }
});

test("调律师：协调额度每个全局回合开始重置且跨两个玩家回合可再次触发", async () => {
  const a = makePlayer("coordination-global-turn-a", 0, "dusk", "ai"),
    tuner = makePlayer("coordination-global-turn-tuner", 1, "dawn", "ai", 7),
    b = makePlayer("coordination-global-turn-b", 2, "dusk", "ai"),
    ally = makePlayer("coordination-global-turn-ally", 3, "dawn");
  const { game } = makeGame([a, tuner, b, ally]);
  registerPassiveSkills(game);
  game.aiController.selectAction = async () => ({ type: "end" });
  game.state.deck.cards.push(
    instance("block"), instance("charge"), instance("assault"),
    instance("shield"), instance("duel"), instance("recover"),
    instance("harvest"), instance("energyDevice"), instance("mutualBenefit"),
    instance("leverage"), instance("telescope"), instance("lightning")
  );
  const drawReasons = [];
  game.eventDispatcher.on("afterCardMove", "test:coordination-cross-turn-draws", (event) => {
    if (event.from === "deck" && event.to === "hand") drawReasons.push(event.reason);
  });
  const validEvent = () => game.eventDispatcher.emit(
    "cardUsed", {
    source: tuner, card: instance("shield"), targets: [ally],
    resolved: true, effectiveTargets: [ally]
  }
  );
  // A 回合：调律师通过成功反制使队友成为有效目标并触发协调。
  await validEvent();
  assert.equal(tuner.turnFlags.coordinationTriggered, true);
  assert.equal(drawReasons.filter((reason) => reason === "协调").length, 1);
  // 同一回合第二次合法事件不再触发。
  await validEvent();
  assert.equal(drawReasons.filter((reason) => reason === "协调").length, 1);
  // B 新回合开始：协调额度重置。
  await game.takeTurn(b, game.state.gameId);
  assert.equal(tuner.turnFlags.coordinationTriggered, false);
  // B 回合再次形成合法协调事件可再次触发。
  await validEvent();
  assert.equal(drawReasons.filter((reason) => reason === "协调").length, 2);
});

