test("AI·借势：有牌拒绝与无牌拒绝经过相同思考提示且日志不泄露原因", async () => {
  const run = async (withAssault) => {
    const actor = makePlayer(`actor-${withAssault}`, 0, "dawn"),
      first = makePlayer(`first-${withAssault}`, 1, "dusk"),
      equipment = instance("energyDevice"),
      use = instance("leverage");
    actor.hand.push(use);
    first.equipment = equipment;
    if (withAssault) first.hand.push(instance("assault"));
    const { game, ui }
      = makeGame([actor, first]);
    game.aiController.responsePolicy.shouldRespond = () => false;
    const prompts = [];
    ui.setPrompt = (message) => prompts.push(message);
    await game.playCard(
      actor, use, [], { firstTargetId: first.id, equipmentCardId: equipment.id, secondTargetId: actor.id }
    );
    return {
      thinking: ui.thinking.map((entry) => entry[0]),
      prompts,
      logs: ui.logs.filter((message) => message.includes("拒绝使用「突袭」"))
    };
  };
  const without = await run(false), withCard = await run(true);
  assert.deepEqual(without.thinking, [true, false]);
  assert.deepEqual(withCard.thinking, [true, false]);
  assert.deepEqual(without.prompts, []);
  assert.deepEqual(withCard.prompts, []);
  assert.equal(without.logs.length, 1);
  assert.equal(withCard.logs.length, 1);
  assert.ok(without.logs.every((message) => !/没有|次数|无法|距离/.test(message)));
  assert.ok(withCard.logs.every((message) => !/没有|次数|无法|距离/.test(message)));
});

