test("AI·望远镜与屏障：确定合法距离保持概率1且条件技能次数不会重复消费同一分支", () => {
  const state = {
    playPhaseEnded: false,
    players: [
      {
        id: "actor",
        seatIndex: 0,
        battleTeam: "dawn",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 4,
        handCount: 0,
        hand: [],
        activeSkillId: "stealSkill",
        activeSkillUses: 0,
        activeSkillLimit: 2,
        activeSkillUsed: false
      },
      {
        id: "target",
        seatIndex: 1,
        battleTeam: "dusk",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        handCount: 2
      }
    ]
  };
  const { game }
    = makeGame([makePlayer("real-a", 0, "dawn"), makePlayer("real-b", 1, "dusk")]);
  const first = game.aiController.actionGenerator.generateFromVisible(
    state, "actor"
  ).find((action) => action.type === "skill");
  assert.equal(first.executionProbability, 1);
  const once = new Simulator(state).apply(state, first, "actor");
  const second = game.aiController.actionGenerator.generateFromVisible(
    once, "actor"
  ).find((action) => action.type === "skill");
  assert.equal(second.executionProbability, 1);
  assert.notEqual(second.skillUseSlot, first.skillUseSlot);
  const twice = new Simulator(once).apply(once, second, "actor");
  assert.ok(
    !game.aiController.actionGenerator.generateFromVisible(
      twice, "actor"
    ).some((action) => action.type === "skill")
  );
});

test("AI·望远镜与屏障：同一卡牌只消费相交分支，另一张牌仍可复用同一望远镜世界", () => {
  const state = {
    playPhaseEnded: false,
    players: [
      {
        id: "actor",
        seatIndex: 0,
        battleTeam: "dawn",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        handCount: 2,
        hand: [{ id: "one", definitionId: "assault" }, { id: "two", definitionId: "assault" }],
        attackUsed: 0,
        attackLimit: 2,
        attackRange: 1,
        equipmentDefinitionId: "telescope",
        equipmentRetentionProbability: .4
      },
      {
        id: "near",
        seatIndex: 1,
        battleTeam: "dusk",
        alive: true,
        hp: 6,
        maxHp: 6,
        shield: 0,
        handCount: 0,
        blockProbability: 0,
        expectedRecoverCount: 0
      },
      {
        id: "far",
        seatIndex: 2,
        battleTeam: "dusk",
        alive: true,
        hp: 6,
        maxHp: 6,
        shield: 0,
        handCount: 0,
        blockProbability: 0,
        expectedRecoverCount: 0
      },
      { id: "ally", seatIndex: 3, battleTeam: "dawn", alive: true, hp: 4, maxHp: 4, handCount: 0 },
      { id: "tail", seatIndex: 4, battleTeam: "dawn", alive: true, hp: 4, maxHp: 4, handCount: 0 }
    ]
  };
  const { game }
    = makeGame([makePlayer("real-a", 0, "dawn"), makePlayer("real-b", 1, "dusk")]);
  const generated = game.aiController.actionGenerator.generateFromVisible(state, "actor");
  const farFirst = generated.find(
    (action) => action.card?.id === "one" && action.targets[0]?.id === "far"
  );
  assertClose(farFirst.executionProbability, .4);
  const once = new Simulator(state).apply(state, farFirst, "actor");
  const follow = game.aiController.actionGenerator.generateFromVisible(once, "actor");
  assert.ok(!follow.some((action) => action.card?.id === "one" && action.targets[0]?.id === "far"));
  assertClose(
    follow.find(
      (action) => action.card?.id === "one" && action.targets[0]?.id === "near"
    ).executionProbability,
    .6
  );
  assertClose(
    follow.find(
      (action) => action.card?.id === "two" && action.targets[0]?.id === "far"
    ).executionProbability,
    .4
  );
});

test("AI·望远镜与屏障：望远镜与目标屏障组合分支各计一次且不重复质量", () => {
  const source = {
    id: "source",
    seatIndex: 0,
    battleTeam: "dawn",
    alive: true,
    equipmentDefinitionId: "telescope",
    equipmentRetentionProbability: .4
  };
  const target = {
    id: "target",
    seatIndex: 2,
    battleTeam: "dusk",
    alive: true,
    equipmentDefinitionId: "barrierDevice",
    equipmentRetentionProbability: .25
  };
  const game = {
    state: {
      players: [
        source,
        { id: "middle", seatIndex: 1, alive: true },
        target,
        { id: "tail", seatIndex: 3, alive: true }
      ]
    }
  };
  const branches = getRangeConditionBranches(game, { source, target, range: 1 });
  assert.equal(branches.length, 4);
  assertClose(branches.reduce((sum, branch) => sum + branch.probability, 0), 1);
  assert.equal(new Set(branches.map((branch) => JSON.stringify(branch.conditions))).size, 4);
  assertClose(
    branches.filter((branch) => branch.matches).reduce((sum, branch) => sum + branch.probability, 0), .3
  );
});

test("AI·望远镜与屏障：stateUtility 感知屏障挡住多个敌人的攻击暴露", () => {
  const { game }
    = makeGame([
      makePlayer("barrier-score-viewer", 0, "dawn", "ai", 3),
      makePlayer("barrier-score-b", 1, "dusk"),
      makePlayer("barrier-score-c", 2, "dusk")
    ]);
  const evaluator = game.aiController.evaluator,
    viewer = {
      id: "barrier-score-viewer",
      seatIndex: 0,
      battleTeam: "dawn",
      characterId: "shade-agent",
      alive: true,
      hp: 4,
      maxHp: 4,
      shield: 0,
      energy: 0,
      handCount: 0,
      hand: [],
      attackRange: 1,
      expectedEquipmentGain: 0,
      expectedEquipmentRoleDelta: 0,
      huntMarkProbabilities: {},
      exposeWeaknessStacks: 0,
      statuses: [],
      expectedInformationGain: 0
    },
    enemy = (id, seatIndex) => ({
      id,
      seatIndex,
      battleTeam: "dusk",
      characterId: "blade-walker",
      alive: true,
      hp: 4,
      maxHp: 4,
      shield: 0,
      energy: 1,
      handCount: 3,
      expectedAssaultCount: 3,
      assaultResponseProbability: 1,
      attackRange: 1,
      expectedEquipmentGain: 0,
      expectedEquipmentRoleDelta: 0,
      huntMarkProbabilities: {},
      exposeWeaknessStacks: 0,
      statuses: [],
      expectedInformationGain: 0
    });
  // 敌人对象统一按攻击范围参数重建
  const enemyWithRange = (id, seatIndex, attackRange) => ({
    ...enemy(id, seatIndex),
    attackRange
  });
  const buildWorld = (barrier, enemyAttackRange = 1) => ({
    players: [
      barrier
        ? {
          ...viewer,
          equipmentDefinitionId: "barrierDevice",
          equipmentRetentionProbability: 1,
          initialEquipmentValue: getBaseCardAiValue("barrierDevice"),
          initialEquipmentRoleDelta: 0
        }
        : {
          ...viewer,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          initialEquipmentValue: 0,
          initialEquipmentRoleDelta: 0
        },
      enemyWithRange("barrier-score-b", 1, enemyAttackRange),
      enemyWithRange("barrier-score-c", 2, enemyAttackRange)
    ]
  });
  const barrierScore = evaluator.stateUtility(buildWorld(true), "barrier-score-viewer"),
    noBarrierScore = evaluator.stateUtility(buildWorld(false), "barrier-score-viewer");
  assert.ok(barrierScore > noBarrierScore);
  // 两名满威胁敌人各贡献 (1 + 3×0.5 + 1×0.3)×5 = 14 暴露分
  assert.ok(barrierScore - noBarrierScore >= 20);
  // 控制组：敌人本就不在攻击范围时，屏障不产生任何分数差异，证明差异来自范围暴露而非屏障名加分
  assert.equal(
    evaluator.stateUtility(buildWorld(true, 0), "barrier-score-viewer"),
    evaluator.stateUtility(buildWorld(false, 0), "barrier-score-viewer")
  );
});

test("AI·望远镜与屏障：屏障挡住两个敌人时不会为略高静态装备拆掉屏障", async () => {
  const actor = makePlayer("barrier-decision-actor", 0, "dawn", "ai", 3),
    b = makePlayer("barrier-decision-b", 1, "dusk"),
    c = makePlayer("barrier-decision-c", 2, "dusk"),
    radar = instance("defenseDevice");
  actor.equipment = instance("barrierDevice");
  actor.hand.push(radar);
  b.energy = 1;
  c.energy = 1;
  b.hand.push(instance("assault"), instance("assault"), instance("assault"));
  c.hand.push(instance("assault"), instance("assault"), instance("assault"));
  // 让 AI 合法记忆敌人的突袭身份：新 exposure 模型用已知 assault summary 计价威胁。
  actor.aiMemory.knownCardsByPlayer[b.id] = Object.fromEntries(b.hand.map((card) => [card.id, "assault"]));
  actor.aiMemory.knownCardsByPlayer[c.id] = Object.fromEntries(c.hand.map((card) => [card.id, "assault"]));
  const { game }
    = makeGame([actor, b, c]);
  game.aiSearchNodeBudgetOverride = 2;
  game.aiRandomnessRange = 0;
  const visible = createInitialSearchState(
    actor.id, game.state, game.aiController.knowledge.remainingCounts(actor)
  );
  const selected = await game.aiController.planner.plan(
    actor,
    visible,
    [{ type: "card", card: radar, targets: [] }, { type: "end" }],
    { gameId: game.state.gameId }
  );
  assert.equal(selected.type, "end");
});

test("AI·望远镜与屏障：屏障未挡住任何人时静态降级换装按真实价值拒绝", async () => {
  const actor = makePlayer("barrier-flex-actor", 0, "dawn", "ai", 0),
    filler = makePlayer("barrier-flex-filler", 1, "dawn"),
    b = makePlayer("barrier-flex-b", 2, "dusk"),
    c = makePlayer("barrier-flex-c", 3, "dusk"),
    filler2 = makePlayer("barrier-flex-filler2", 4, "dawn"),
    telescope = instance("telescope");
  actor.equipment = instance("barrierDevice");
  actor.hand.push(telescope);
  const { game }
    = makeGame([actor, filler, b, c, filler2]);
  game.aiSearchNodeBudgetOverride = 2;
  game.aiRandomnessRange = 0;
  const visible = createInitialSearchState(
    actor.id, game.state, game.aiController.knowledge.remainingCounts(actor)
  );
  const selected = await game.aiController.planner.plan(
    actor,
    visible,
    [{ type: "card", card: telescope, targets: [] }, { type: "end" }],
    { gameId: game.state.gameId }
  );
  // 屏障(9)→望远镜(8) 在统一价值中为静态降级（无敌人被屏障挡住时尤其如此），
  // 旧实现靠 end 固定 -0.8 强制换装；新机会成本语义按真实边际拒绝负收益 sibling。
  assert.equal(selected.type, "end", "静态降级换装（真实负收益 sibling）不应被固定 end 惩罚强制执行");
});

