test("AI·反制概率：已知1+匿名50%反制后身份保留0.25且只存在于count1世界", () => {
  const target = counterPlayer(
    "b",
    "dusk",
    {
      handCount: 2,
      knownCards: [counterKnownCard("k1")],
      counterCountDistribution: [
        { probability: .5, conditions: { anon: "no" }, counterCount: 1 },
        { probability: .5, conditions: { anon: "yes" }, counterCount: 2 }
      ]
    }
  );
  const state = { players: [counterPlayer("a", "dawn"), target] };
  const simulator = new Simulator({ players: [] });
  const next = simulator.apply(
    state, { type: "card", card: { ...CARD_DEFINITIONS.shockwave, id: "sw" }, targets: [] }, "a"
  );
  const targetAfter = next.players[1];
  const kept = targetAfter.knownCards.find((entry) => entry.cardId === "k1");
  assert.ok(kept);
  assertClose(simulator.cardAvailability(kept), .25);
  const joint = joinProbabilityStateBranches(
    projectAvailability(kept.availabilityStateBranches, "keptAvail"),
    targetAfter.counterCountDistribution.map(
      ({ probability, conditions, counterCount }) => (
        { probability, conditions, count1: counterCount === 1 }
      )
    )
  );
  const impossible = joint.filter(
    (branch) => branch.keptAvail && !branch.count1
  ).reduce((sum, branch) => sum + branch.probability, 0);
  assert.ok(Math.abs(impossible) < 1e-9);
  const byCount = counterByCount(targetAfter);
  assertClose(byCount[0] ?? 0, .5);
  assertClose(byCount[1] ?? 0, .5);
});

test("AI·反制概率：两张已知反制一次互斥选择且第二次消费剩余一张", () => {
  const target = counterPlayer(
    "b",
    "dusk",
    {
      handCount: 2, counterProbability: 1, knownCards: [counterKnownCard("k1"), counterKnownCard("k2")]
    }
  );
  const state = { players: [counterPlayer("a", "dawn"), target] };
  const simulator = new Simulator({ players: [] });
  let next = simulator.apply(
    state, { type: "card", card: { ...CARD_DEFINITIONS.shockwave, id: "sw" }, targets: [] }, "a"
  );
  const after1 = next.players[1];
  assert.equal(after1.knownCards.length, 2);
  assertClose(counterAvailability(after1.knownCards.find((entry) => entry.cardId === "k1")), .5);
  assertClose(counterAvailability(after1.knownCards.find((entry) => entry.cardId === "k2")), .5);
  const joint1 = joinProbabilityStateBranches(
    projectAvailability(
      after1.knownCards.find((entry) => entry.cardId === "k1").availabilityStateBranches, "a1"
    ),
    projectAvailability(
      after1.knownCards.find((entry) => entry.cardId === "k2").availabilityStateBranches, "a2"
    )
  );
  const bothKept = joint1.filter(
    (branch) => branch.a1 && branch.a2
  ).reduce((sum, branch) => sum + branch.probability, 0);
  const bothGone = joint1.filter(
    (branch) => !branch.a1 && !branch.a2
  ).reduce((sum, branch) => sum + branch.probability, 0);
  assert.ok(Math.abs(bothKept) < 1e-9);
  assert.ok(Math.abs(bothGone) < 1e-9);
  const byCount = counterByCount(after1);
  assertClose(byCount[1] ?? 0, 1);
  next = simulator.apply(
    next, { type: "card", card: { ...CARD_DEFINITIONS.provoke, id: "pv" }, targets: [] }, "a"
  );
  assert.equal(next.players[1].knownCards.length, 0);
  assert.equal(counterProbabilityOf(next.players[1]), 0);
});

