const counterDrawActor = (overrides = {}) => (
  {
    id: "a",
    seatIndex: 0,
    battleTeam: "dawn",
    characterId: "blade-walker",
    alive: true,
    hp: 4,
    maxHp: 4,
    shield: 0,
    handCount: 1,
    counterProbability: 0,
    blockProbability: 0,
    twoBlockProbability: 0,
    expectedRecoverCount: 0,
    expectedAssaultCount: 0,
    assaultResponseProbability: 0,
    expectedInformationGain: 0,
    equipmentDefinitionId: null,
    equipmentRetentionProbability: 0,
    statuses: [],
    ...overrides
  }
);

test("AI·反制先验：丰收摸两张并叠加两次新牌反制先验", () => {
  const actor = counterDrawActor(
    {
      handCount: 1,
      hand: [{ id: "h", definitionId: "harvest" }],
      counterCountDistribution: [{ probability: 1, conditions: {}, counterCount: 0 }]
    }
  );
  const state = {
    remainingCardCounts: { counter: 1, charge: 1 }, players: [actor, counterPlayer("e", "dusk", { seatIndex: 1 })]
  };
  const next = new Simulator(
    state
  ).apply(state, { type: "card", card: { ...CARD_DEFINITIONS.harvest, id: "h" }, targets: [] }, "a");
  const after = next.players[0];
  assert.equal(after.handCount, 2);
  const byCount = counterByCount(after);
  assertClose(byCount[0] ?? 0, .25);
  assertClose(byCount[1] ?? 0, .5);
  assertClose(byCount[2] ?? 0, .25);
  assertClose(after.counterProbability, .75);
  assertClose(after.counterCountDistribution.reduce((sum, branch) => sum + branch.probability, 0), 1);
});

test("AI·反制先验：旧反制消费后再丰收只产生新牌先验", () => {
  const actor = counterDrawActor(
    { handCount: 2, hand: [{ id: "c", definitionId: "counter" }, { id: "h", definitionId: "harvest" }] }
  );
  const state = { players: [actor, counterPlayer("e", "dusk", { seatIndex: 1 })] };
  const simulator = new Simulator(state);
  simulator.consumeTargetCounterResponseWorlds(
    state, actor, [{ probability: 1, conditions: {}, occurs: true }], 1
  );
  assert.equal(actor.handCount, 1);
  assert.equal(actor.hand[0].definitionId, "harvest");
  assert.equal(counterProbabilityOf(actor), 0);
  state.remainingCardCounts = { counter: 1, charge: 1 };
  const next = simulator.apply(
    state, { type: "card", card: { ...CARD_DEFINITIONS.harvest, id: "h" }, targets: [] }, "a"
  );
  const after = next.players[0];
  assert.equal(after.handCount, 2);
  const byCount = counterByCount(after);
  assertClose(byCount[0] ?? 0, .25);
  assertClose(byCount[1] ?? 0, .5);
  assertClose(byCount[2] ?? 0, .25);
  assert.equal(after.hand.some((card) => card.definitionId === "counter"), false);
});

