test("AI·格挡概率：格挡决策随可用格挡数单调且先验证实际支付数量", () => {
  const responder = makePlayer("block-policy", 0, "dawn", "ai"),
    ally1 = makePlayer("block-ally-1", 1, "dawn"),
    enemy1 = makePlayer("block-enemy-1", 2, "dusk"),
    ally2 = makePlayer("block-ally-2", 3, "dawn"),
    enemy2 = makePlayer("block-enemy-2", 4, "dusk");
  const { game }
    = makeGame([responder, ally1, enemy1, ally2, enemy2]), policy = game.aiController.responsePolicy;
  const decisions = [];
  for (const count of [1, 2, 3]) {
    responder.hand = [
      ...Array.from({ length: count }, () => instance("block")),
      ...Array.from({ length: 4 - count }, () => instance("charge"))
    ];
    decisions.push(
      policy.shouldRespond(
        responder,
        "block",
        { target: responder, amount: 1, requiredCount: 1 },
        responder.hand.filter((card) => card.definitionId === "block")
      )
    );
  }
  assert.ok(!decisions.some((decision, index) => index > 0 && decisions[index - 1] && !decision));
  responder.hp = 1;
  responder.shield = 0;
  responder.hand = [instance("block")];
  assert.equal(
    policy.shouldRespond(
      responder, "block", { target: responder, amount: 1, requiredCount: 1 }, responder.hand
    ),
    true
  );
  responder.hp = 2;
  assert.equal(
    policy.shouldRespond(
      responder, "block", { target: responder, amount: 1, requiredCount: 1 }, responder.hand
    ),
    true
  );
  assert.equal(
    policy.shouldRespond(
      responder, "block", { target: responder, amount: 2, requiredCount: 2 }, responder.hand
    ),
    false
  );
});

test("AI·格挡概率：真实响应预览连势孤注且不重复计算破势", async () => {
  const run = async ({ characterIndex, momentum = 0, allIn = false, exposeWeakness = 0 }) => {
    const source = makePlayer(`block-preview-source-${characterIndex}`, 0, "dawn", "ai", characterIndex),
      target = makePlayer(`block-preview-target-${characterIndex}`, 1, "dusk", "ai", 3),
      targetAllyA = makePlayer(`block-preview-target-ally-a-${characterIndex}`, 2, "dusk", "ai", 5),
      targetAllyB = makePlayer(`block-preview-target-ally-b-${characterIndex}`, 3, "dusk", "ai", 7),
      sourceAlly = makePlayer(`block-preview-source-ally-${characterIndex}`, 4, "dawn", "ai", 4),
      assault = instance("assault"),
      block = instance("block");
    const { game } = makeGame([source, target, targetAllyA, targetAllyB, sourceAlly]);
    registerPassiveSkills(game);
    source.hand.push(assault);
    source.turnFlags.momentum = momentum;
    if (momentum) source.turnFlags.categoriesUsed.add("basic");
    if (allIn) source.statuses.allIn = { assaultBonus: 1 };
    if (exposeWeakness) source.statuses.exposeWeakness = { stacks: exposeWeakness };
    target.hp = 3;
    target.hand.push(block, instance("charge"), instance("shield"), instance("assault"));
    const rawAmounts = [], policy = game.aiController.responsePolicy,
      originalShouldRespond = policy.shouldRespond.bind(policy);
    policy.shouldRespond = (responder, type, context, cards) => {
      if (type === "block") rawAmounts.push(context.amount);
      return originalShouldRespond(responder, type, context, cards);
    };
    assert.equal(await game.playCard(source, assault, [target]), true);
    return { source, target, block, rawAmounts };
  };

  const momentum = await run({ characterIndex: 0, momentum: 2 });
  assert.deepEqual(momentum.rawAmounts, [1]);
  assert.equal(momentum.target.hp, 3);
  assert.equal(momentum.target.alive, true);
  assert.equal(momentum.target.hand.includes(momentum.block), false);
  assert.equal(momentum.source.turnFlags.momentum, 2);

  const allIn = await run({ characterIndex: 6, allIn: true, exposeWeakness: 1 });
  assert.deepEqual(allIn.rawAmounts, [2]);
  assert.equal(allIn.target.hp, 3);
  assert.equal(allIn.target.hand.includes(allIn.block), false);
  assert.equal(allIn.source.statuses.allIn, undefined);

  const exposeWeakness = await run({ characterIndex: 4, exposeWeakness: 2 });
  assert.deepEqual(exposeWeakness.rawAmounts, [3]);
  assert.equal(exposeWeakness.target.hp, 3);
  assert.equal(exposeWeakness.target.hand.includes(exposeWeakness.block), false);
});

