      {
        id: "ally", seatIndex: 1, battleTeam: "dawn", alive: true, hp: 3, maxHp: 3, shield: 0, handCount: 0
      },
      {
        id: "enemy", seatIndex: 2, battleTeam: "dusk", alive: true, hp: 3, maxHp: 3, shield: 0, handCount: 0
      }
