test("AI·救援：强制救援：真人救队友时仍可自行接受或拒绝", async () => {
  const run = async (decision) => {
    const target = makePlayer(`target-${decision}`, 0, "dawn"),
      human = makePlayer(`human-${decision}`, 1, "dawn", "human"),
      enemy = makePlayer(`enemy-${decision}`, 2, "dusk");
    target.hp = 0;
    human.hand.push(instance("recover"));
    const fixture = makeGame([target, human, enemy], { response: () => decision });
    await fixture.game.dyingWorkflow.enter(target, enemy);
    return { target, human, ui: fixture.ui };
  };
  const declined = await run(false), accepted = await run(true);
  assert.equal(declined.target.alive, false);
  assert.equal(declined.human.hand.length, 1);
  assert.equal(declined.ui.responseRequests.length, 1);
  assert.equal(accepted.target.alive, true);
  assert.equal(accepted.target.hp, 1);
  assert.equal(accepted.human.hand.length, 0);
  assert.equal(accepted.ui.responseRequests.length, 1);
});

