test("AI·角色卡牌价值：26 张正式基础值与名称、definitionId 全部匹配", () => {
  const actual = Object.fromEntries(
    Object.values(CARD_DEFINITIONS).map(
      (definition) => [
        definition.definitionId,
        [definition.name, getBaseCardAiValue(definition.definitionId)]
      ]
    )
  );
  assert.deepEqual(actual, EXPECTED_CARD_AI_VALUES);
  for (const [definitionId, [, expectedValue]] of Object.entries(EXPECTED_CARD_AI_VALUES)) {
    assert.equal(getBaseCardAiValue(definitionId), expectedValue);
  }
});

test("AI·角色卡牌价值：八名角色 ID 与 135 项正式非零差值全部匹配", () => {
  assert.deepEqual(
    Object.fromEntries(CHARACTER_DEFINITIONS.map((character) => [character.id, character.name])),
    EXPECTED_ROLE_NAMES
  );
  assert.deepEqual(validateRoleCardValueDeltas(ROLE_CARD_VALUE_DELTAS), []);
  assert.deepEqual(ROLE_CARD_VALUE_DELTAS, EXPECTED_ROLE_CARD_VALUE_DELTAS);
  assert.equal(
    Object.values(ROLE_CARD_VALUE_DELTAS).reduce((sum, deltas) => sum + Object.keys(deltas).length, 0),
    135
  );
});

test("AI·角色卡牌价值：八名角色乘 26 张牌的差值与最终值全部匹配", () => {
  for (const [characterId, expectedDeltas] of Object.entries(EXPECTED_ROLE_CARD_VALUE_DELTAS)) {
    for (const [definitionId, [, baseValue]] of Object.entries(EXPECTED_CARD_AI_VALUES)) {
      const expectedDelta = expectedDeltas[definitionId] ?? 0;
      assert.equal(ROLE_CARD_VALUE_DELTAS[characterId]?.[definitionId] ?? 0, expectedDelta);
      assert.equal(
        getRoleCardAiValue(characterId, definitionId), baseValue + expectedDelta,
        `${characterId}/${definitionId}`
      );
      if (expectedDelta === 0) {
        assert.equal(Object.hasOwn(ROLE_CARD_VALUE_DELTAS[characterId], definitionId), false);
      }
    }
  }
});

test("AI·角色卡牌价值：新增角色未配置差值时自动回退基础值", () => {
  const futureCharacterDefinitions = [...CHARACTER_DEFINITIONS, Object.freeze({ id: "future-role" })];
  const deltas = Object.freeze({ "blade-walker": Object.freeze({ assault: 1 }) });
  for (const definition of Object.values(CARD_DEFINITIONS)) {
    assert.equal(
      getRoleCardAiValue(
        "future-role", definition.definitionId, { characterDefinitions: futureCharacterDefinitions, deltas }
      ),
      getBaseCardAiValue(definition.definitionId)
    );
  }
  assert.deepEqual(
    validateRoleCardValueDeltas(deltas, { characterDefinitions: futureCharacterDefinitions }), []
  );
});

test("AI·角色卡牌价值：新增卡牌未配置差值时自动回退基础值", () => {
  const futureCardDefinitions = {
    ...CARD_DEFINITIONS, futureCard: Object.freeze({ definitionId: "futureCard", aiValue: 4 })
  };
  const deltas = Object.freeze({ "blade-walker": Object.freeze({ assault: 1 }) });
  for (const character of CHARACTER_DEFINITIONS) {
    assert.equal(
      getRoleCardAiValue(character.id, "futureCard", { cardDefinitions: futureCardDefinitions }), 4
    );
  }
  assert.equal(getBaseCardAiValue("futureCard", futureCardDefinitions), 4);
  assert.deepEqual(
    validateRoleCardValueDeltas(deltas, { cardDefinitions: futureCardDefinitions }), []
  );
});

test("AI·角色卡牌价值：稀疏差值只作用于配置的组合", () => {
  const deltas = Object.freeze({ "blade-walker": Object.freeze({ assault: 1 }) });
  assert.deepEqual(validateRoleCardValueDeltas(deltas), []);
  assert.equal(
    getRoleCardAiValue("blade-walker", "assault", { deltas }), getBaseCardAiValue("assault") + 1
  );
  assert.equal(
    getRoleCardAiValue("blade-walker", "recover", { deltas }), getBaseCardAiValue("recover")
  );
  assert.equal(
    getRoleCardAiValue("oath-warden", "assault", { deltas }), getBaseCardAiValue("assault")
  );
});

test("AI·角色卡牌价值：边界差值 -2 与 +2 合法", () => {
  const deltas = Object.freeze(
    { "blade-walker": Object.freeze({ assault: -2 }), "oath-warden": Object.freeze({ recover: 2 }) }
  );
  assert.deepEqual(validateRoleCardValueDeltas(deltas), []);
  assert.equal(
    getRoleCardAiValue("blade-walker", "assault", { deltas }), getBaseCardAiValue("assault") - 2
  );
  assert.equal(
    getRoleCardAiValue("oath-warden", "recover", { deltas }), getBaseCardAiValue("recover") + 2
  );
});

test("AI·角色卡牌价值：无效差值配置被拒绝", () => {
  const contains = (errors, fragment) => errors.some((message) => message.includes(fragment));
  assert.ok(contains(validateRoleCardValueDeltas({ "not-a-role": { assault: 1 } }), "not-a-role"));
  assert.ok(
    contains(validateRoleCardValueDeltas({ "blade-walker": { "not-a-card": 1 } }), "not-a-card")
  );
  assert.ok(contains(validateRoleCardValueDeltas({ "blade-walker": { assault: 0.5 } }), "assault"));
  assert.ok(contains(validateRoleCardValueDeltas({ "blade-walker": { assault: NaN } }), "assault"));
  assert.ok(
    contains(validateRoleCardValueDeltas({ "blade-walker": { assault: Infinity } }), "assault")
  );
  assert.ok(contains(validateRoleCardValueDeltas({ "blade-walker": { assault: -3 } }), "-3"));
  assert.ok(contains(validateRoleCardValueDeltas({ "blade-walker": { assault: 3 } }), "3"));
  assert.ok(validateRoleCardValueDeltas(null).length > 0);
  assert.ok(validateRoleCardValueDeltas([]).length > 0);
  assert.ok(validateRoleCardValueDeltas({ "blade-walker": [] }).length > 0);
});

test("AI·角色卡牌价值：运行时未知角色或卡牌 ID 抛出可定位错误", () => {
  assert.throws(() => getRoleCardAiValue("unknown-role", "assault"), /unknown-role/);
  assert.throws(() => getRoleCardAiValue("blade-walker", "unknown-card"), /unknown-card/);
  assert.throws(() => getBaseCardAiValue("unknown-card"), /unknown-card/);
  assert.throws(() => getRoleCardAiValue(undefined, "assault"), /undefined/);
});

test("AI·角色卡牌价值：差值表顶层与全部角色对象均冻结且保持稀疏", () => {
  assert.equal(Object.isFrozen(ROLE_CARD_VALUE_DELTAS), true);
  for (const [characterId, roleDeltas] of Object.entries(ROLE_CARD_VALUE_DELTAS)) {
    assert.equal(Object.isFrozen(roleDeltas), true);
    assert.ok(Object.keys(roleDeltas).length > 0, `${characterId} 不应为空对象`);
    for (const [definitionId, delta] of Object.entries(roleDeltas)) {
      assert.notEqual(delta, 0, `${characterId}/${definitionId} 不应显式配置 0`);
    }
  }
  assert.throws(() => {
    ROLE_CARD_VALUE_DELTAS["blade-walker"] = { assault: 1 };
  }, TypeError);
  assert.throws(() => {
    ROLE_CARD_VALUE_DELTAS["blade-walker"]["assault"] = 2;
  }, TypeError);
});

test("AI·角色卡牌价值：Getter 直接拒绝非法差值", () => {
  for (const badDelta of [0.5, NaN, Infinity, -3, 3, "1"]) {
    const deltas = Object.freeze({ "blade-walker": Object.freeze({ assault: badDelta }) });
    assert.throws(() => getRoleCardAiValue("blade-walker", "assault", { deltas }), (error) => {
      const message = String(error?.message ?? error);
      return message.includes(
        "blade-walker"
      ) && message.includes("assault") && message.includes(String(badDelta));
    });
  }
});

test("AI·角色卡牌价值：Getter 拒绝非法基础值", () => {
  const badDefinitions = [
    { aiValue: NaN }, { aiValue: Infinity }, { aiValue: "4" }, { definitionId: "badCard" }
  ];
  for (const badDefinition of badDefinitions) {
    const cardDefinitions = {
      ...CARD_DEFINITIONS, badCard: Object.freeze({ definitionId: "badCard", ...badDefinition })
    };
    assert.throws(() => getBaseCardAiValue("badCard", cardDefinitions), /badCard/);
    assert.throws(() => getRoleCardAiValue("blade-walker", "badCard", { cardDefinitions }), /badCard/);
  }
});

test("AI·角色卡牌价值：正式有效值全部位于 3 到 11", () => {
  for (const character of CHARACTER_DEFINITIONS) {
    for (const definition of Object.values(CARD_DEFINITIONS)) {
      const value = getRoleCardAiValue(character.id, definition.definitionId);
      assert.ok(value >= 3 && value <= 11, `${character.id}/${definition.definitionId}=${value}`);
    }
  }
});

