test("AI·转移评分：目标反制风险下转移部分生效且来源与接收者身份互补", () => {
  const state = {
    playPhaseEnded: false,
    remainingCardCounts: { assault: 10 },
    players: [
      {
        id: "a",
        seatIndex: 0,
        battleTeam: "dawn",
        characterId: "blade-walker",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        handCount: 1,
        hand: [{ id: "use", definitionId: "transfer" }],
        attackRange: 1,
        equipmentDefinitionId: null,
        equipmentRetentionProbability: 0,
        counterProbability: 0
      },
      {
        id: "s",
        seatIndex: 1,
        battleTeam: "dusk",
        characterId: "oath-warden",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        handCount: 1,
        knownCards: [
          {
            cardId: "known-assault",
            definitionId: "assault",
            availabilityBranches: [{ probability: 1, conditions: {} }],
            availabilityStateBranches: [{ probability: 1, conditions: {}, available: true }]
          }
        ],
        counterProbability: 1
      },
      {
        id: "r",
        seatIndex: 2,
        battleTeam: "dawn",
        characterId: "spirit-medic",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        handCount: 0,
        counterProbability: 0
      }
    ]
  };
  const { game }
    = makeGame([makePlayer("real", 0, "dawn"), makePlayer("real-b", 1, "dusk")]);
  const action = game.aiController.actionGenerator.generateFromVisible(
    state, "a"
  ).find((entry) => entry.card?.definitionId === "transfer");
  assert.ok(action);
  assert.equal(action.selection.selectionKind, "known");
  const simulator = new Simulator(state), next = simulator.apply(state, action, "a");
  const nextActor = next.players[0], nextSource = next.players[1], nextReceiver = next.players[2];
  assert.equal(nextActor.hand.some((card) => card.id === "use"), false);
  // 来源确定持有一张反制，统一动态反制意愿 = clamp(转移 generic 价值/机会成本) = 11/14：
  // 反制概率 1 × 11/14 → 11/14 世界反制取消、3/14 世界转移成功，来源/接收者身份互补。
  assertClose(nextSource.handCount, 11 / 14);
  const sourceAssault = nextSource.knownCards.find((entry) => entry.cardId === "known-assault");
  assert.ok(sourceAssault);
  assertClose(simulator.cardAvailability(sourceAssault), 11 / 14);
  // 生成动作的接收者是行动者自己；转移成功世界进入行动者手牌。
  assertClose(nextActor.handCount, 3 / 14);
  const receiverAssault = nextActor.hand.find((card) => card.id === "known-assault");
  assert.ok(receiverAssault);
  assertClose(simulator.cardAvailability(receiverAssault), 3 / 14);
  assert.equal(nextReceiver.handCount, 0);
});

