test("UI·玩家面板：目标选择期间头像与名称优先选择目标且不打开技能面板", () => {
  const source = makePlayer("source", 0, "dawn", "human"),
    target = makePlayer("target", 1, "dusk"),
    illegal = makePlayer("illegal", 2, "dawn"),
    other = makePlayer("other", 3, "dawn");
  let resolved = null, shown = null, triggerUsed = null, rendered = 0;
  const makeState = () => (
    { players: [target], legalIds: new Set([target.id]), resolve: (value) => { resolved = value; } }
  );
  const makeFake = () => (
    {
      game: { state: { players: [source, target, illegal, other] } },
      targetState: null,
      showSkillDetails: (value, trigger) => { shown = value; triggerUsed = trigger; },
      render: () => { rendered += 1; },
      playSound() { }
    }
  );
  const panelFor = (player) => ({ dataset: { playerId: player.id } }),
    skillFor = (player) => ({ dataset: { skillPlayerId: player.id } }),
    eventFor = (player, kind) => (
      {
        target: {
          closest: (query) => query === "[data-skill-player-id]" && [
            "avatar", "name"
          ].includes(kind) ? skillFor(player) : query === "[data-player-id]" ? panelFor(player) : null
        }
      }
    );
  let ui = makeFake();
  UIManager.prototype.handlePlayerClick.call(ui, eventFor(target, "avatar"));
  assert.equal(shown, target);
  assert.equal(triggerUsed.dataset.skillPlayerId, target.id);
  assert.equal(ui.targetState, null);
  shown = null;
  triggerUsed = null;
  UIManager.prototype.handlePlayerClick.call(ui, eventFor(other, "name"));
  assert.equal(shown, other);
  assert.equal(ui.targetState, null);
  shown = null;
  ui = makeFake();
  ui.targetState = makeState();
  UIManager.prototype.handlePlayerClick.call(ui, eventFor(target, "avatar"));
  assert.equal(resolved, target);
  assert.equal(shown, null);
  assert.equal(ui.targetState, null);
  assert.equal(rendered, 1);
  resolved = null;
  ui = makeFake();
  ui.targetState = makeState();
  UIManager.prototype.handlePlayerClick.call(ui, eventFor(target, "name"));
  assert.equal(resolved, target);
  assert.equal(shown, null);
  assert.equal(ui.targetState, null);
  resolved = null;
  ui = makeFake();
  ui.targetState = makeState();
  UIManager.prototype.handlePlayerClick.call(ui, eventFor(illegal, "avatar"));
  assert.equal(resolved, null);
  assert.equal(shown, null);
  assert.ok(ui.targetState);
  assert.equal(ui.targetState.legalIds.has(target.id), true);
  resolved = null;
  ui = makeFake();
  ui.targetState = makeState();
  UIManager.prototype.handlePlayerClick.call(ui, eventFor(illegal, "name"));
  assert.equal(resolved, null);
  assert.equal(shown, null);
  assert.ok(ui.targetState);
  resolved = null;
  rendered = 0;
  ui = makeFake();
  ui.targetState = makeState();
  UIManager.prototype.handlePlayerClick.call(ui, eventFor(target, "panel"));
  assert.equal(resolved, target);
  assert.equal(shown, null);
  assert.equal(ui.targetState, null);
  assert.equal(rendered, 1);
});

