test("UI·响应窗口：转移响应片段包含来源与接收者的队伍", async () => {
  const actor = makePlayer("actor", 0, "dawn"),
    from = makePlayer("from", 1, "dusk"),
    responder = makePlayer("responder", 2, "dusk", "human"),
    receiver = makePlayer("receiver", 3, "dawn");
  const use = instance("transfer"), secret = instance("block");
  actor.hand.push(use);
  from.hand.push(secret);
  from.bumpHandVersion(TEST_VERSION_STATE);
  const { game, ui }
    = makeGame([actor, from, responder, receiver], { response: () => false });
  const hidden = game.hiddenCardSelection.createHiddenSelection(from);
  await game.playCard(
    actor,
    use,
    [],
    {
      sourceId: from.id,
      receiverId: receiver.id,
      tokens: [hidden.tokens[0].token],
      selectionId: hidden.selectionId
    }
  );
  const request = ui.responseRequests.find(
    (entry) => entry.type === "counter" && entry.targetPlayerId === responder.id
  );
  assert.ok(request);
  const fragments = request.presentation.eventFragments;
  assert.equal(
    fragments.find(
      (fragment) => fragment.type === "player" && fragment.playerId === actor.id
    ).battleTeam,
    "dawn"
  );
  assert.equal(
    fragments.find((fragment) => fragment.type === "player" && fragment.playerId === from.id).battleTeam,
    "dusk"
  );
  assert.equal(
    fragments.find(
      (fragment) => fragment.type === "player" && fragment.playerId === receiver.id
    ).battleTeam,
    "dawn"
  );
  assert.match(request.presentation.eventText, new RegExp(`${from.name}.*1张牌.*${receiver.name}`));
});

