test("生命周期：beforeCardMove 取消出牌时保持手牌且不产生出牌统计或事件", async () => {
  const ai = makePlayer("cancel-move-ai", 0, "dawn"),
    enemy = makePlayer("cancel-move-enemy", 1, "dusk"),
    card = instance("charge"),
    { game }
      = makeGame([ai, enemy]);
  ai.hand.push(card);
  let used = 0;
  game.eventDispatcher.on("beforeCardMove", "test:cancel-ai-card-move", (event) => {
    if (event.card === card) event.cancelled = true;
  });
  game.eventDispatcher.on("cardUsed", "test:no-card-used-after-cancel", () => {
    used += 1;
  });
  assert.equal(await game.playCard(ai, card, []), false);
  assert.deepEqual(ai.hand, [card]);
  assert.equal(game.state.resolvingCards.length, 0);
  assert.equal(game.state.discardPile.length, 0);
  assert.equal(ai.statistics.cardsPlayed, 0);
  assert.equal(used, 0);
  assert.equal(game.actionLocked, false);
});

test("生命周期：beforeCardMove 取消 AI 动作后游戏循环仍推进至下一角色", async () => {
  const ai = makePlayer("cancel-loop-ai", 0, "dawn"),
    next = makePlayer("cancel-loop-next", 1, "dusk"),
    card = instance("charge"),
    { game }
      = makeGame([ai, next]);
  ai.hand.push(card);
  game.aiController.getActionCandidates = () => [];
  game.aiController.selectAction = async () => ({ type: "card", card, targets: [] });
  game.eventDispatcher.on("beforeCardMove", "test:cancel-loop-card", (event) => {
    if (event.card === card) event.cancelled = true;
  });
  let nextStarted = false;
  game.eventDispatcher.on("turnStart", "test:cancel-loop-next-turn", (event) => {
    if (event.player === next) {
      nextStarted = true;
      game.state.isGameOver = true;
    }
  });
  game.loopPromise = game.runGameLoop();
  await assert.doesNotReject(game.loopPromise);
  assert.equal(nextStarted, true);
  assert.deepEqual(ai.hand, [card]);
  assert.equal(game.state.resolvingCards.length, 0);
  assert.equal(game.actionLocked, false);
});

