  enemy.hand.push(instance("assault"));
  const { game, ui }
    = makeGame([human, ally, enemy]);
  const waiting = ui.waitForHumanPlayEnd(game.state.gameId);
  assert.equal(await game.handleHumanCard(duel.id), true);
